head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldods70005";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — comList, param.keyValue, spotIsuTrdMktTpCd

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_fillGen();
        scwin.init_conds();
        await scwin.init_loadList();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldods70005.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_if_39", fn: function(){ return ((((dma_pageContext.get("comList") ?? "")) && typeof ((dma_pageContext.get("comList") ?? "")).getRowCount === 'function' ? ((dma_pageContext.get("comList") ?? "")).getRowCount() : ((((dma_pageContext.get("comList") ?? "")) === null) ? 0 : (((dma_pageContext.get("comList") ?? "")).length || 0))) === 0); } }, { id: "removeCheckId11", fn: function(){ return ((((dma_pageContext.get("comList") ?? "")) && typeof ((dma_pageContext.get("comList") ?? "")).getRowCount === 'function' ? ((dma_pageContext.get("comList") ?? "")).getRowCount() : ((((dma_pageContext.get("comList") ?? "")) === null) ? 0 : (((dma_pageContext.get("comList") ?? "")).length || 0))) === 0); } }, { id: "if_majSubcomYn_txt", fn: function(){ return ((dlt_comList.getCellData(0, "majSubcomYn") ?? (() => { throw new Error("unresolved:" + "result.majSubcomYn"); })()) === 'Y'); } }, { id: "if_majSubcomYn_2_txt", fn: function(){ return ((dlt_comList.getCellData(0, "majSubcomYn") ?? (() => { throw new Error("unresolved:" + "result.majSubcomYn"); })()) === 'N'); } }, { id: "if_keyValue", fn: function(){ return ((dma_pageContext.get("keyValue") ?? "") === 'TBLD_O_SUBCOM_STAT'); } }, { id: "tr_25", fn: function(){ return ((dma_pageContext.get("keyValue") ?? "") === 'TBLD_O_SUBCOM_STAT'); } }, { id: "tr_33", fn: function(){ return ((dma_pageContext.get("keyValue") ?? "") === 'TBLD_O_SUBCOM_STAT'); } }, { id: "removeCheckId11", fn: function(){ return ((dma_pageContext.get("keyValue") ?? "") === 'TBLD_O_SUBCOM_STAT'); } }, { id: "removeCheckId1", fn: function(){ return ((dma_pageContext.get("keyValue") ?? "") === 'TBLD_O_SUBCOM_STAT'); } }, { id: "c_if_96", fn: function(){ return ((((dma_pageContext.get("comList") ?? "")) && typeof ((dma_pageContext.get("comList") ?? "")).getRowCount === 'function' ? ((dma_pageContext.get("comList") ?? "")).getRowCount() : ((((dma_pageContext.get("comList") ?? "")) === null) ? 0 : (((dma_pageContext.get("comList") ?? "")).length || 0))) === 0); } }, { id: "removeCheckId11_2", fn: function(){ return ((((dma_pageContext.get("comList") ?? "")) && typeof ((dma_pageContext.get("comList") ?? "")).getRowCount === 'function' ? ((dma_pageContext.get("comList") ?? "")).getRowCount() : ((((dma_pageContext.get("comList") ?? "")) === null) ? 0 : (((dma_pageContext.get("comList") ?? "")).length || 0))) === 0); } }, { id: "if_exchBasSubscomYn_txt", fn: function(){ return ((dlt_comList.getCellData(0, "exchBasSubscomYn") ?? (() => { throw new Error("unresolved:" + "result.exchBasSubscomYn"); })()) === 'Y'); } }, { id: "if_exchBasSubscomYn_2_txt", fn: function(){ return ((dlt_comList.getCellData(0, "exchBasSubscomYn") ?? (() => { throw new Error("unresolved:" + "result.exchBasSubscomYn"); })()) === 'N'); } }, { id: "if_fssBasSubscomYn_txt", fn: function(){ return ((dlt_comList.getCellData(0, "fssBasSubscomYn") ?? (() => { throw new Error("unresolved:" + "result.fssBasSubscomYn"); })()) === 'Y'); } }, { id: "if_fssBasSubscomYn_2_txt", fn: function(){ return ((dlt_comList.getCellData(0, "fssBasSubscomYn") ?? (() => { throw new Error("unresolved:" + "result.fssBasSubscomYn"); })()) === 'N'); } }, { id: "if_keyValue_2", fn: function(){ return ((dma_pageContext.get("keyValue") ?? "") === 'TBLD_O_SUBSCOM_STAT'); } }, { id: "tr_79", fn: function(){ return ((dma_pageContext.get("keyValue") ?? "") === 'TBLD_O_SUBSCOM_STAT'); } }, { id: "tr_88", fn: function(){ return ((dma_pageContext.get("keyValue") ?? "") === 'TBLD_O_SUBSCOM_STAT'); } }, { id: "removeCheckId11_2", fn: function(){ return ((dma_pageContext.get("keyValue") ?? "") === 'TBLD_O_SUBSCOM_STAT'); } }, { id: "removeCheckId2", fn: function(){ return ((dma_pageContext.get("keyValue") ?? "") === 'TBLD_O_SUBSCOM_STAT'); } }, { id: "if_spotIsuTrdMktTpCd", fn: function(){ return ((dma_pageContext.get("spotIsuTrdMktTpCd") ?? "") === 1); } }, { id: "th_144", fn: function(){ return ((dma_pageContext.get("spotIsuTrdMktTpCd") ?? "") === 1); } }, { id: "th_145", fn: function(){ return ((dma_pageContext.get("spotIsuTrdMktTpCd") ?? "") === 1); } }, { id: "th_147", fn: function(){ return ((dma_pageContext.get("spotIsuTrdMktTpCd") ?? "") !== 1); } }, { id: "if_spotIsuTrdMktTpCd_4", fn: function(){ return ((dma_pageContext.get("spotIsuTrdMktTpCd") ?? "") === 1); } }, { id: "removeCheckId11_3", fn: function(){ return ((dma_pageContext.get("spotIsuTrdMktTpCd") ?? "") === 1); } }, { id: "if_spotIsuTrdMktTpCd_5", fn: function(){ return ((dma_pageContext.get("spotIsuTrdMktTpCd") ?? "") !== 1); } }, { id: "removeCheckId11_4", fn: function(){ return ((dma_pageContext.get("spotIsuTrdMktTpCd") ?? "") !== 1); } }, { id: "if_spotIsuTrdMktTpCd_4", fn: function(){ return ((((dma_pageContext.get("comList") ?? "")) && typeof ((dma_pageContext.get("comList") ?? "")).getRowCount === 'function' ? ((dma_pageContext.get("comList") ?? "")).getRowCount() : ((((dma_pageContext.get("comList") ?? "")) === null) ? 0 : (((dma_pageContext.get("comList") ?? "")).length || 0))) === 0); } }, { id: "if_spotIsuTrdMktTpCd_5", fn: function(){ return ((((dma_pageContext.get("comList") ?? "")) && typeof ((dma_pageContext.get("comList") ?? "")).getRowCount === 'function' ? ((dma_pageContext.get("comList") ?? "")).getRowCount() : ((((dma_pageContext.get("comList") ?? "")) === null) ? 0 : (((dma_pageContext.get("comList") ?? "")).length || 0))) === 0); } }, { id: "removeCheckId11_3", fn: function(){ return ((((dma_pageContext.get("comList") ?? "")) && typeof ((dma_pageContext.get("comList") ?? "")).getRowCount === 'function' ? ((dma_pageContext.get("comList") ?? "")).getRowCount() : ((((dma_pageContext.get("comList") ?? "")) === null) ? 0 : (((dma_pageContext.get("comList") ?? "")).length || 0))) === 0); } }, { id: "removeCheckId11_4", fn: function(){ return ((((dma_pageContext.get("comList") ?? "")) && typeof ((dma_pageContext.get("comList") ?? "")).getRowCount === 'function' ? ((dma_pageContext.get("comList") ?? "")).getRowCount() : ((((dma_pageContext.get("comList") ?? "")) === null) ? 0 : (((dma_pageContext.get("comList") ?? "")).length || 0))) === 0); } }, { id: "if_spotIsuTrdMktTpCd_6", fn: function(){ return ((dma_pageContext.get("spotIsuTrdMktTpCd") ?? "") === 1); } }, { id: "if_keyValue_3", fn: function(){ return ((dma_pageContext.get("keyValue") ?? "") === 'TBLD_O_OTHCORP_CONTRB_STAT'); } }, { id: "tr_141", fn: function(){ return ((dma_pageContext.get("keyValue") ?? "") === 'TBLD_O_OTHCORP_CONTRB_STAT'); } }, { id: "removeCheckId11_3", fn: function(){ return ((dma_pageContext.get("keyValue") ?? "") === 'TBLD_O_OTHCORP_CONTRB_STAT'); } }, { id: "removeCheckId11_4", fn: function(){ return ((dma_pageContext.get("keyValue") ?? "") === 'TBLD_O_OTHCORP_CONTRB_STAT'); } }, { id: "removeCheckId1_2", fn: function(){ return ((dma_pageContext.get("keyValue") ?? "") === 'TBLD_O_OTHCORP_CONTRB_STAT'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        const ok = !!b.fn();
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_fillGen
 * @description 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
 * @param {String} boxId boxId
 * @returns {void}
 * @hidden N
 */
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_42", entity: "dlt_comList", countIds: [], cells: [{ childId: "ipt_selectedIdx", fn: function (v, i) { return String(i); } }, { childId: "__rc0", fn: function (v, i) { return String(v("comNm")); } }, { childId: "__rc1", fn: function (v, i) { return String(v("ceoNm")); } }, { childId: "__rc2", fn: function (v, i) { return String(v("majBzContn")); } }, { childId: "__rc3", fn: function (v, i) { return String(v("asstTotamt")); } }, { childId: "__rc4", fn: function (v, i) { return String(v("debtTotamt")); } }, { childId: "__rc5", fn: function (v, i) { return String(v("capTotamt")); } }, { childId: "__rc6", fn: function (v, i) { return String(v("cap")); } }, { childId: "__rc7", fn: function (v, i) { return String(v("incldDd")); } }] },
        { genId: "c_foreach_99", entity: "dlt_comList", countIds: [], cells: [{ childId: "ipt_selectedIdx_2", fn: function (v, i) { return String(i); } }, { childId: "__rc8", fn: function (v, i) { return String(v("comKorNm")); } }, { childId: "__rc9", fn: function (v, i) { return String(v("comEngNm")); } }, { childId: "__rc10", fn: function (v, i) { return String(v("foundDd")); } }, { childId: "__rc11", fn: function (v, i) { return String(v("incldDd")); } }, { childId: "__rc12", fn: function (v, i) { return String(v("ceoNm")); } }, { childId: "__rc13", fn: function (v, i) { return String(v("majBzContn")); } }, { childId: "__rc14", fn: function (v, i) { return String(v("asstTotamt")); } }, { childId: "__rc15", fn: function (v, i) { return String(v("connAsstTotamt")); } }] },
        { genId: "c_foreach_163", entity: "dlt_comList", countIds: [], cells: [{ childId: "ipt_selectedIdx_3", fn: function (v, i) { return String(i); } }, { childId: "__rc16", fn: function (v, i) { return String(v("comKorNm")); } }, { childId: "__rc17", fn: function (v, i) { return String(v("nat")); } }, { childId: "__rc18", fn: function (v, i) { return String(v("ceoNm")); } }, { childId: "__rc19", fn: function (v, i) { return String(v("majBzContn")); } }, { childId: "__rc20", fn: function (v, i) { return String(v("cap")); } }, { childId: "__rc21", fn: function (v, i) { return String(v("isuShrs")); } }, { childId: "__rc22", fn: function (v, i) { return String(v("acqstAmt")); } }, { childId: "__rc23", fn: function (v, i) { return String(v("acqstMethdContn")); } }, { childId: "__rc24", fn: function (v, i) { return String(v("acqstSchdlDd")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getRowCount();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.titleChange();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods70005.onpageload' }); }
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_submit). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_selectThis();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_selectThis_onclick
 * @description 「선택」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_selectThis_onclick = async function(e){
    try {
        await scwin.selectThis()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods70005.btn_selectThis_onclick' }); }
};

/**
 * @method
 * @name btn_window_onclick
 * @description 「취소」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_window_onclick = function(e){
    try {
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods70005.btn_window_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_selectThis
 * @description select This 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_selectThis = async function () {
    // ⛔주소를 정할 수 없다 — as-is 문서 위치를 못 찾았다(⛔못 쟀다 — as-is JSP 위치 미상).
    //   추정 주소로 내보내면 «엉뚱한 곳으로 조용히» 나간다. 불릴 때 드러나게 실패시킨다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "제출 주소를 찾지 못했습니다(전환 미완) — disclosureCommon.do"
    throw { bizMessage: "제출 주소를 찾지 못했습니다(전환 미완) — disclosureCommon.do", unresolved: "action:disclosureCommon.do" };
};

/**
 * @method
 * @name titleChange
 * @description title Change 처리
 * @returns {void}
 * @hidden N
 */
scwin.titleChange = function () {
    const titleTp = '' + dma_pageContext.get("keyValue") + '';
    if (titleTp === "TBLD_O_SUBCOM_STAT") {
        $("#popup_title").text("자회사 선택");
    } else {
        if (titleTp === "TBLD_O_SUBSCOM_STAT") {
            $("#popup_title").text("종속회사 선택");
        } else {
            if (titleTp === "TBLD_O_OTHCORP_CONTRB_STAT") {
                $("#popup_title").text("타법인 선택");
            }
        }
    }
};

/**
 * @method
 * @name selectThis
 * @description select This 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.selectThis = async function () {
    const frm = (document.form || { elements: [] });
    if (($c.util.getComponent('dlt_comList').getRowCount() > 0) !== null) {
        if ($c.util.getComponent('dlt_comList').getRowCount() > 1) {
            if (isChecked(($c.util.getComponent('dlt_comList').getRowCount() > 0))) {
                frm.action = "disclosureCommon.do";
                await scwin.tx_selectThis();
            } else {
                await $c.win.alert("하나의 회사를 선택하시기 바랍니다.");
            }
        } else {
            if (($c.util.getComponent('dlt_comList').getRowCount() > 0).checked === false) {
                await $c.win.alert("하나의 회사를 선택하시기 바랍니다.");
            } else {
                frm.action = "disclosureCommon.do";
                await scwin.tx_selectThis();
            }
        }
    } else {

    }
    function isChecked(ver) {
        let isOk = false;
        for (let i = 0; i < ver.length; i++) {
            if (ver[i].checked) {
                isOk = true;
            }
        }
        return isOk;
    }
};

/**
 * @method
 * @name isChecked
 * @description is Checked 처리
 * @param {*} ver ver
 * @returns {void}
 * @hidden N
 */
scwin.isChecked = function (ver) {
    let isOk = false;
    for (let i = 0; i < ver.length; i++) {
        if (ver[i].checked) {
            isOk = true;
        }
    }
    return isOk;
};
